import http.client,json,os,pathlib,tempfile,time,urllib.parse,yaml
ROOT=pathlib.Path.cwd()
TARGETS=[ROOT/'live/file/runtime.yaml',ROOT/'live/http/runtime.json']
def read_regular(path):
    if path.is_symlink() or not path.is_file():raise ValueError('regular file required')
    if path.stat().st_size>65536:raise ValueError('artifact too large')
    return path.read_bytes()
def replace(path,data):
    fd,tmp=tempfile.mkstemp(prefix='.rollout-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as out:out.write(data);out.flush();os.fsync(out.fileno())
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
def report(status):
    replace(ROOT/'rollout.json',json.dumps({'status':status}).encode())
def matches(context,expected):
    p=urllib.parse.urlsplit(context['entry_url'])
    for host,want in expected.items():
        conn=http.client.HTTPConnection(p.hostname,p.port,timeout=.25)
        try:
            conn.request('GET','/',headers={'Host':host});res=conn.getresponse()
            body=res.read(1024).decode('utf8')
            if res.status!=200 or body!=want['body'] or res.getheader('X-Release')!=want['release']:return False
        except (OSError,ValueError,http.client.HTTPException):return False
        finally:conn.close()
    return True
def wait(context,expected):
    deadline=time.monotonic()+3
    while time.monotonic()<deadline:
        if matches(context,expected):return True
        time.sleep(.05)
    return False
def main():
    try:
        context=json.loads(read_regular(ROOT/'context.json'))
        url=urllib.parse.urlsplit(context['entry_url'])
        if url.scheme!='http' or url.hostname!='127.0.0.1' or not 1024<=url.port<=65535 or url.path or url.query or url.fragment or url.username:raise ValueError('loopback entry required')
        for group in ('old','new'):
            if set(context[group])!={'public.lab.test','private.lab.test'}:raise ValueError('fixed route contract')
            for expected in context[group].values():
                if set(expected)!={'body','release'} or not all(isinstance(v,str) and len(v)<128 for v in expected.values()):raise ValueError('expected response contract')
        if any(p.is_symlink() for p in [ROOT/'live',ROOT/'live/file',ROOT/'live/http',ROOT/'rollout.json']):raise ValueError('symlink target rejected')
        previous=[read_regular(p) for p in TARGETS]
        candidates=[read_regular(ROOT/'candidate-file.yaml'),read_regular(ROOT/'candidate-http.json')]
        for parsed in (yaml.safe_load(candidates[0]),json.loads(candidates[1])):
            if not isinstance(parsed,dict) or not isinstance(parsed.get('http'),dict):raise ValueError('HTTP dynamic document required')
        if not wait(context,context['old']):raise ValueError('baseline not healthy')
    except (ValueError,OSError,KeyError,TypeError,yaml.YAMLError):report('rejected');return 2
