        if not wait(context,context['new']):raise RuntimeError('candidate routes not healthy')
        report('committed');return 0
    except (OSError,RuntimeError):
        try:
            for path,data in zip(TARGETS,previous):replace(path,data)
            restored=wait(context,context['old'])
        except OSError:restored=False
        report('rolled_back' if restored else 'rollback_failed');return 1
